defmodule Mix.Tasks.LiveLift.Compile do
  use Mix.Task

  @shortdoc "Compiles app LiveLift.Client views to a JavaScript registry"

  @impl Mix.Task
  def run(args) do
    {opts, modules, invalid} =
      OptionParser.parse(args,
        strict: [output: :string, runtime_output: :string, split: :boolean]
      )

    unless invalid == [] and modules == [] and is_binary(opts[:output]) do
      Mix.raise(
        "usage: mix live_lift.compile --output assets/js/generated_views.js [--runtime-output assets/js/live_lift_runtime.js] [--split]"
      )
    end

    Mix.Task.run("compile")

    app = Mix.Project.config()[:app]

    case Application.load(app) do
      :ok -> :ok
      {:error, {:already_loaded, ^app}} -> :ok
    end

    view_modules =
      app
      |> Application.spec(:modules)
      |> Enum.filter(fn module ->
        Code.ensure_loaded?(module) and
          function_exported?(module, :__live_lift_client_template__, 0) and
          is_list(module.__live_lift_client_template__())
      end)

    output = Path.expand(opts[:output])

    runtime_output =
      Path.expand(
        opts[:runtime_output] || Path.join(Path.dirname(output), "live_lift_runtime.js")
      )

    if runtime_output == output do
      Mix.raise("registry and runtime outputs must use different paths")
    end

    File.mkdir_p!(Path.dirname(output))

    if opts[:split] do
      write_split_registry(view_modules, output)
    else
      write_registry(view_modules, output)
    end

    File.mkdir_p!(Path.dirname(runtime_output))

    runtime_source = Path.expand("../../../assets/js/live_lift/client_hook.js", __DIR__)
    File.cp!(runtime_source, runtime_output)

    Mix.shell().info("Generated #{Path.relative_to_cwd(output)} (#{length(view_modules)} views)")
    Mix.shell().info("Copied #{Path.relative_to_cwd(runtime_output)}")
  end

  defp write_registry(modules, output) do
    {registry, source_map} =
      LiveLift.Client.Compiler.compile_registry_with_map(modules, output)

    File.write!(output, registry <> "//# sourceMappingURL=#{Path.basename(output)}.map\n")
    File.write!(output <> ".map", source_map)
  end

  defp write_split_registry(modules, output) do
    directory = Path.rootname(output) <> "_views"
    File.mkdir_p!(directory)
    relative_directory = Path.basename(directory)

    entries =
      modules
      |> Enum.reject(&function_exported?(&1, :__live_lift_component__, 0))
      |> Enum.sort()
      |> Enum.map(fn module ->
        name = Atom.to_string(module) |> String.replace_prefix("Elixir.", "")
        filename = URI.encode(name, &URI.char_unreserved?/1) <> ".js"
        write_registry([module], Path.join(directory, filename))
        import_path = Jason.encode!("./#{relative_directory}/#{filename}")
        "  [#{Jason.encode!(name)}]: () => import(#{import_path})"
      end)

    File.write!(
      output,
      "// Generated by LiveLift. Do not edit.\nexport const views = {\n" <>
        Enum.join(entries, ",\n") <> "\n};\n"
    )
  end
end
